ValidationRule.errorConditionFormula:
AND(
    OR(RecordType.DeveloperName = "NewOperationalTest", RecordType.DeveloperName = "OldNewOperationalTest"),
    OR(
        AND(
            ISPICKVAL(StageName__c, "フェーズ10 運用方法確定"),
            OR(
                NOT(INCLUDES(CompletionBasis__c, "10-1:顧客の現場責任者と打ち合わせを行い、運用方法、配置を確定した。")),
                NOT(INCLUDES(CompletionBasis__c, "10-2:TANAX内での運用に関する打ち合わせを完了した。")),
                NOT(INCLUDES(CompletionBasis__c, "10-3:お客様の役員決裁に向けて資料を作成し、アポイントを確定した。"))
            )
        )
    )
)
